ALTER TABLE "public"."textile_products" ENABLE TRIGGER "trg_create_default_textile_variant";

-- Restore the every-product-has-a-variant invariant for seeded products that
-- came without variants (a few test rows from the production export).
INSERT INTO "public"."textile_variants" ("product_id", "color", "size", "is_default", "sort_order")
SELECT "p"."id", 'Standard', 'One size', true, 1
FROM "public"."textile_products" "p"
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."textile_variants" "v" WHERE "v"."product_id" = "p"."id"
